script:
class Component extends DCLogic {
me() { try { return parent.SONNA_USER || null; } catch (e) { return null; } }
usedOf(codes) { const o = {}; (codes || []).forEach((c) => { o[c] = true; }); return o; }
api(m, u, b) { try { return parent.SONNA_API(m, u, b); } catch (e) { return Promise.reject(e); } }
shared(k, d) { try { var S = parent.SONNA_STORE; return S ? S.get(k, d) : d; } catch (e) { return d; } }
state = {
view: 'home', catId: '', itemId: '', qty: 1, q: '', menuOpen: false, banner: 0, logged: !!this.me(), wallet: null, authMode: 'login', authUser: '', authPass: '', authErr: '', authBack: 'home', busy: false, payErr: '',
input: '', tryCode: '', paid: false, paidInfo: null,
used: this.usedOf((this.me() || {}).usedCodes), orders: this.me() ? (parent.SONNA_ORDERS || []).slice() : [], open: {}, sold: this.shared('sold', {}),
topTab: 'bank', amount: 100000, amtRaw: '100000', topMsg: '', telco: 'Viettel', face: 100000, serial: '', pin: '', cardMsg: false, cardErr: false
};
mount() {
setInterval(() => {
const s = this.state;
if (s.view !== 'topup' || !s.logged || !this.me()) return;
const cur = this.state.wallet === null ? Number(this.me().wallet) : this.state.wallet;
this.api('GET', '/api/user/me').then((r) => {
if (!r.user) return;
if (r.user.wallet > cur) this.setState({ wallet: r.user.wallet, topMsg: 'Đã nhận tiền! Ví +' + String(r.user.wallet - cur).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫.' });
else if (r.user.wallet !== cur) this.setState({ wallet: r.user.wallet });
}).catch(() => {});
}, 4000);
}
renderVals() {
const st = this.state;
const savedTheme = this.shared('brandTheme', null) || {};
const validHex = (value, fallback) => /^#[0-9a-f]{6}$/i.test(value || '') ? value : fallback;
const contrastText = (hex) => { const rgb = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255).map((v) => v <= 0.04045 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)); const luminance = 0.2126 * rgb[0] + 0.7152 * rgb[1] + 0.0722 * rgb[2]; return 1.05 / (luminance + 0.05) >= (luminance + 0.05) / 0.052 ? '#FFFFFF' : '#1A1206'; };
const themeColors = { primary: validHex(savedTheme.primary, '#2D0A3F'), mid: validHex(savedTheme.mid, '#3F1457'), deep: validHex(savedTheme.deep, '#220733'), tint: validHex(savedTheme.tint, '#F3E8F9'), border: validHex(savedTheme.border, '#D9CFE6'), footerMuted: validHex(savedTheme.footerMuted, '#B8A3CF'), accent: validHex(savedTheme.accent, '#FF8A1F'), accentLight: validHex(savedTheme.accentLight, '#FFC24B'), text: validHex(savedTheme.text, '#FFFFFF'), midText: contrastText(validHex(savedTheme.mid, '#3F1457')) };
const fmt = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.') + '₫';
const baseWallet = this.me() ? Number(this.me().wallet) || 0 : 0;
const CFG = (() => { try { return parent.SONNA_CONFIG || {}; } catch (e) { return {}; } })();
const PAY = Object.assign({ contentPrefix: 'SONNA', ready: false }, CFG.payment || {});
const qrUrl = (PAY.ready && st.logged && this.me() && st.amount > 0 && PAY.qrTemplate) ? PAY.qrTemplate.replace('{acc}', encodeURIComponent(PAY.accountNumber)).replace('{bank}', encodeURIComponent(PAY.bankShortName)).replace('{amount}', String(st.amount)).replace('{des}', encodeURIComponent(PAY.contentPrefix + this.me().id)) : '';
const wallet = st.wallet === null ? baseWallet : st.wallet;
const norm = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[đĐ]/g, 'd').toLowerCase();

const CATALOG = this.shared('catalog', null);
const CATS = [
{ id: 'ra', name: 'Reroll DBL Android', kind: 'pack', col: themeColors.primary, symbol: '🎲', platform: 'ANDROID' },
{ id: 'ri', name: 'Reroll DBL iOS', kind: 'pack', col: '#2F6FD6', symbol: '🎲', platform: 'iOS' },
{ id: 'ca', name: 'Character + Chrono Android', kind: 'single', col: '#C2273D', symbol: '🌟', platform: 'ANDROID' },
{ id: 'ci', name: 'Character + Chrono iOS', kind: 'single', col: '#0E8F8F', symbol: '🌟', platform: 'iOS' },
{ id: 'tm', name: 'Team Meta', kind: 'single', col: '#D9780F', symbol: '⚔️', platform: 'TEAM META' }
];
if (CATALOG && Array.isArray(CATALOG.categories)) CATALOG.categories.forEach((c) => { if (c && c.id && c.name) CATS.push({ id: c.id, name: c.name, kind: 'single', col: c.color || themeColors.primary, symbol: '📁', platform: c.platform || 'Khác', custom: true }); });
let PACKS = [
{ id: 'ra50', cat: 'ra', title: 'DBL 50K-55K APK', stock: 12, sold: 390, price: 10000, gift: true },
{ id: 'ra60', cat: 'ra', title: 'DBL 60K-65K APK', stock: 14, sold: 258, price: 20000, gift: false },
{ id: 'ra70', cat: 'ra', title: 'DBL 70K-75K APK', stock: 19, sold: 69, price: 45000, gift: false },
{ id: 'ra80', cat: 'ra', title: 'DBL 80K-85K APK', stock: 5, sold: 62, price: 80000, gift: false },
{ id: 'ra90', cat: 'ra', title: 'DBL 90K-95K APK', stock: 0, sold: 48, price: 100000, gift: false },
{ id: 'ri50', cat: 'ri', title: 'DBL 50K-55K iOS', stock: 26, sold: 251, price: 18000, gift: true },
{ id: 'ri60', cat: 'ri', title: 'DBL 60K-65K iOS', stock: 41, sold: 162, price: 30000, gift: false },
{ id: 'ri70', cat: 'ri', title: 'DBL 70K-75K iOS', stock: 21, sold: 66, price: 60000, gift: false }
];
let SINGLES = [
{ id: 'CA-1042', cat: 'ca', level: 118, crystal: '12.400', chars: 46, price: 1250000 },
{ id: 'CA-1039', cat: 'ca', level: 142, crystal: '21.050', chars: 68, price: 3400000 },
{ id: 'CA-1037', cat: 'ca', level: 74, crystal: '2.300', chars: 19, price: 320000 },
{ id: 'CI-1041', cat: 'ci', level: 96, crystal: '5.800', chars: 31, price: 690000 },
{ id: 'CI-1034', cat: 'ci', level: 131, crystal: '15.900', chars: 55, price: 2150000 },
{ id: 'TM-0008', cat: 'tm', level: 110, crystal: '8.200', chars: 40, price: 1800000 },
{ id: 'TM-0011', cat: 'tm', level: 125, crystal: '9.900', chars: 52, price: 2600000 }
];
if (CATALOG) {
const MAPC = { 'reroll-android': 'ra', 'reroll-ios': 'ri', 'char-android': 'ca', 'char-ios': 'ci', 'team-meta': 'tm' };
(CATALOG.categories || []).forEach((c) => { if (c && c.id) MAPC[c.id] = c.id; });
PACKS = []; SINGLES = [];
(CATALOG.subs || []).forEach((sb) => { if (!MAPC[sb.cat] || !sb.title) return;
PACKS.push({ id: sb.id, cat: MAPC[sb.cat], title: sb.title, stock: (CATALOG.accts || []).filter((a) => a.sub === sb.id && a.cat !== 'promo' && a.status === 'Đang bán').length, sold: (CATALOG.accts || []).filter((a) => a.sub === sb.id && a.status === 'Đã bán').length, price: sb.price, gift: !!sb.giftOffer || !!sb.gift, giftText: sb.giftOffer ? 'MUA ' + sb.giftOffer.buy + ' TẶNG ' + sb.giftOffer.give : 'MUA 1 TẶNG 1', pics: sb.pics || [] }); });
const singlesCats = ['char-android', 'char-ios', 'team-meta'].concat((CATALOG.categories || []).map((c) => c.id));
(CATALOG.accts || []).forEach((a) => { if (singlesCats.indexOf(a.cat) < 0 || a.status !== 'Đang bán' || a.sub) return;
SINGLES.push({ id: a.id, cat: MAPC[a.cat], title: String(a.title || '').trim() || 'Acc #' + a.id, info: a.info || '', level: a.level || '–', crystal: a.chrono || '–', chars: a.chars || '–', price: a.price, originalPrice: Number(a.originalPrice) || 0, discountPercent: Number(a.discountPercent) || 0, pics: a.pics || [] }); });
}
const catById = (id) => CATS.find((c) => c.id === id);
const catOrder = this.shared('catOrder', null);
const itemOrder = this.shared('itemOrder', {});
const CATS_ORD = CATS.slice().sort((a, b) => { const ia = catOrder ? catOrder.indexOf(a.id) : -1, ib = catOrder ? catOrder.indexOf(b.id) : -1; return (ia < 0 ? 99 : ia) - (ib < 0 ? 99 : ib); });
const rankIn = (it) => { const o = itemOrder[it.cat]; const r = o ? o.indexOf(it.id) : -1; return r < 0 ? 999 : r; };
const items = PACKS.map((p) => ({ ...p, isPack: true })).concat(SINGLES.map((s) => ({ ...s, isPack: false, title: s.title || 'Acc #' + s.id, stock: 1 }))).map((it, i) => ({ ...it, stock: CATALOG ? it.stock : Math.max(0, it.stock - (st.sold[it.id] || 0)), _i: i })).sort((a, b) => (rankIn(a) - rankIn(b)) || (a._i - b._i));
const colOf = (it) => catById(it.cat).col;
const go = (patch) => this.setState({ menuOpen: false, ...patch });

const cardOf = (it) => {
const out = it.stock === 0;
return {
title: it.title, pic: (it.pics || [])[0] || '', hasPic: !!(it.pics && it.pics.length), price: fmt(it.price), originalPrice: fmt(it.originalPrice || 0), salePercent: Number(it.discountPercent) || 0, hasSale: Number(it.discountPercent) > 0, ribbon: !!it.gift, ribbonText: it.giftText || 'MUA 1 TẶNG 1', tag: it.isPack ? (it.cat === 'ra' || it.cat === 'ca' ? '🤖 ANDROID' : (it.cat === 'ri' || it.cat === 'ci' ? '📱 iOS' : '📁 ' + (catById(it.cat) || CATS[0]).name.toUpperCase())) : ((catById(it.cat) || CATS[0]).custom ? ((catById(it.cat) || CATS[0]).platform === 'Android' ? '🤖 ANDROID' : ((catById(it.cat) || CATS[0]).platform === 'iOS' ? '📱 iOS' : '📁 SẢN PHẨM')) : (it.cat === 'tm' ? '⚔ TEAM META' : (it.cat === 'ca' ? '🤖 ANDROID' : '📱 iOS'))),
tagBg: it.cat === 'ra' || it.cat === 'ca' ? '#168A45' : (it.cat === 'ri' || it.cat === 'ci' ? '#2F6FD6' : ((catById(it.cat) || CATS[0]).custom ? (catById(it.cat) || CATS[0]).col : '#D9780F')),
line: it.isPack ? 'Còn lại: ' + it.stock + ' | Đã bán: ' + (it.sold + (st.sold[it.id] || 0)) : ((catById(it.cat) || CATS[0]).custom ? (it.info || (catById(it.cat) || CATS[0]).name) : 'Cấp ' + it.level + ' · ' + it.crystal + ' tinh thể · ' + it.chars + ' nhân vật'),
bg: colOf(it), soldOut: out, btn: out ? 'Hết hàng' : 'Mua ngay', btnBg: out ? '#D6D2E2' : themeColors.accent, btnFg: out ? '#5A5470' : '#1A1206', cursor: out ? 'not-allowed' : 'pointer',
pick: () => go({ view: 'detail', catId: it.cat, itemId: it.id, qty: 1, input: '', tryCode: '', paid: false, paidInfo: null })
};
};

// menu
const menuDefs = [
{ id: 'home', label: 'Trang chủ', pick: () => go({ view: 'home' }) },
{ id: 'cats', label: 'Danh mục ▾', pick: () => this.setState({ menuOpen: !st.menuOpen }) },
{ id: 'topup', label: 'Nạp tiền', pick: () => go({ view: 'topup', topMsg: '' }) },
{ id: 'history', label: 'Lịch sử', pick: () => go({ view: 'history' }) },
{ id: 'guide', label: 'Hướng dẫn', pick: () => go({ view: 'guide' }) }
];
const curMenu = st.view === 'cat' || st.view === 'detail' ? 'cats' : st.view;
const menu = menuDefs.map((m) => ({ label: m.label, pick: m.pick, bg: m.id === curMenu ? themeColors.primary : 'transparent', cur: m.id === curMenu ? 'page' : 'false' }));
const catMenu = CATS_ORD.map((c) => ({ id: c.id, name: c.name, pick: () => go({ view: 'home' }) }));
const catTiles = CATS_ORD.map((c) => ({ id: c.id, name: c.name, col: c.col, symbol: c.symbol, platform: c.platform, pick: () => go({ view: 'home' }) }));

// banners (từ trang Nội dung website nếu có)
const DEFAULT_B = [
{ id: 1, kind: 'main', title: 'ACC REROLL UY TÍN, GIAO TỰ ĐỘNG', link: '', on: true, img: '', kicker: 'SONNA · ACC DRAGON BALL LEGENDS', sub: 'Thanh toán bằng ví, nhận TK|MK ngay sau khi trừ tiền.', bg: 'linear-gradient(120deg,#2D0A3F,#5B1F7A 60%,#8A3FB0)' },
{ id: 2, kind: 'main', title: 'NẠP VÍ THƯỞNG THÊM 5%', link: '', on: true, img: '', kicker: 'KHUYẾN MÃI NẠP', sub: 'Nạp 100.000₫ nhận 105.000₫. Nạp ngân hàng hoặc thẻ cào.', bg: 'linear-gradient(120deg,#102A56,#2F6FD6 70%,#58A0F0)' },
{ id: 3, kind: 'sub', title: 'Mua 1 tặng 1', link: '', on: true, img: '', kicker: '', sub: 'Một số gói reroll được tặng thêm 1 acc cùng loại, giao tự động ngay khi thanh toán. Mua nhiều acc vẫn chỉ tặng 1.', bg: '#fff' }
];
const bAll = this.shared('banners', DEFAULT_B).filter((x) => x.on);
const defaultBannerBg = 'linear-gradient(120deg,#2D0A3F,#5B1F7A 60%,#8A3FB0)';
const themeBannerBg = 'linear-gradient(120deg,' + themeColors.deep + ',' + themeColors.mid + ' 60%,' + themeColors.primary + ')';
const decorate = (x) => ({ title: x.title, kicker: x.kicker || 'SONNA', sub: x.sub || '', bg: !x.bg || x.bg === defaultBannerBg ? themeBannerBg : x.bg, img: x.img || '', hasImg: !!x.img, noImg: !x.img });
const mains = bAll.filter((x) => x.kind === 'main').map(decorate);
const subs = bAll.filter((x) => x.kind === 'sub').map(decorate);
const banner = mains.length ? mains[st.banner % mains.length] : decorate({ title: '' });
const sub = subs.length ? subs[0] : decorate({ title: '' });
const dots = mains.length > 1 ? mains.map((b, i) => ({ n: i + 1, w: i === st.banner % mains.length ? '28px' : '12px', op: i === st.banner % mains.length ? 1 : 0.6, pick: () => this.setState({ banner: i }) })) : [];

// chữ chạy + liên hệ
const MQ = this.shared('marq', { on: true, speed: 'mid', tone: 'orange', text: 'Nạp ví hôm nay nhận thêm 5% giá trị nạp\nAcc được admin đăng nhập kiểm tra trước khi đăng bán\nHỗ trợ qua Zalo trong giờ làm việc' });
const mqLines = String(MQ.text || '').split('\n').map((x) => x.trim()).filter((x) => x !== '');
const mqTone = { orange: [themeColors.accent, '#1A1206'], blue: ['#52C7FF', '#0A1620'], dark: ['#1F2538', '#EAEFFA'] }[MQ.tone] || [themeColors.accent, '#1A1206'];
const mqBase = { slow: 14, mid: 9, fast: 5 }[MQ.speed] || 9;
const mqText = mqLines.join('   •   ');
const mqDur = Math.max(mqBase, Math.round(mqText.length / 8 * (mqBase / 9))) + 's';
const CT = this.shared('contact', { phone: { v: '[SỐ ĐIỆN THOẠI]', on: true }, zalo: { v: '[SỐ ZALO]', on: true }, fanpage: { v: '[LINK FANPAGE]', on: true }, zgroup: { v: '[LINK NHÓM ZALO]', on: true }, email: { v: '[EMAIL HỖ TRỢ]', on: false }, youtube: { v: '[LINK KÊNH YOUTUBE]', on: false } });
const CT_L = { phone: 'Hotline', zalo: 'Zalo', fanpage: 'Fanpage', zgroup: 'Nhóm Zalo', email: 'Email', youtube: 'YouTube' };
const contactLines = Object.keys(CT_L).filter((k) => CT[k] && CT[k].on).map((k) => ({ k: CT_L[k], v: CT[k].v }));
const hours = this.shared('hours', '08:00 - 22:00 hằng ngày');
if (CT.phone && CT.phone.on || CT.zalo && CT.zalo.on) contactLines.push({ k: 'Giờ hỗ trợ', v: hours });

// home sections with search
const qq = norm((st.q || '').trim());
const match = (it) => qq === '' || norm(it.title).indexOf(qq) >= 0 || norm(catById(it.cat).name).indexOf(qq) >= 0 || norm(it.id).indexOf(qq) >= 0;
const sections = CATS_ORD.map((c) => { const categoryItems = items.filter((it) => it.cat === c.id); const cards = categoryItems.filter(match).map(cardOf); const soldCount = categoryItems.reduce((sum, it) => sum + (CATALOG ? (Number(st.sold[it.id]) || 0) : (Number(it.sold) || 0) + (Number(st.sold[it.id]) || 0)), 0); const stockCount = categoryItems.reduce((sum, it) => sum + (Number(it.stock) || 0), 0); return { id: c.id, name: c.name, count: cards.length, cards, color: c.col || themeColors.primary, platform: c.platform || 'Khác', fighter: !c.custom, custom: !!c.custom, soldCount, stockCount, flameClass: (() => { const key = (c.name + ' ' + c.id).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9]/g, ''); return /(?:rerolldbl|dblreroll|charactercc|teammeta)/.test(key); })() ? ' flame-category' : '' }; }).filter((s) => s.cards.length > 0);
const salesDisplay = this.shared('salesDisplay', { enabled: true, limit: 6 }) || { enabled: true, limit: 6 };
const soldAccountCount = Number(this.shared('soldAccountCount', 0)) || 0;
const recentSales = (this.shared('recentSales', []) || []).slice(0, Math.min(12, Math.max(1, Number(salesDisplay.limit) || 6))).map((sale) => { const time = Date.parse(sale.soldAt || ''); return { title: sale.title || 'Acc đã giao', category: sale.category || 'Acc Dragon Ball Legends', image: sale.image || '', hasImage: !!sale.image, time: Number.isFinite(time) ? new Date(time).toLocaleString('vi-VN') : 'Đã giao' }; });
const showRecentSales = salesDisplay.enabled !== false && soldAccountCount > 0;

// category view
const cat = catById(st.catId) || CATS[0];

// detail
const it = items.find((x) => x.id === st.itemId) || items[0];
const qty = it.isPack ? Math.max(1, Math.min(st.qty, it.stock || 1)) : 1;
const price = it.price * qty;
let CODES = {
GIAM10: { kind: 'pct', val: 10, min: 300000, cap: 50000, scope: 'all', until: '31/10/2026', expired: false },
BANMOI: { kind: 'amt', val: 20000, min: 100000, cap: 0, scope: 'all', until: 'Không hết hạn', expired: false },
REROLLIOS: { kind: 'pct', val: 5, min: 0, cap: 0, scope: 'ri', scopeLabel: 'Acc Reroll iOS', until: '20/12/2026', expired: false },
TETVUI: { kind: 'amt', val: 50000, min: 500000, cap: 0, scope: 'all', until: '30/09/2026', expired: true }
};
const SC = { 'Tất cả danh mục': 'all', 'Acc Reroll iOS': 'ri', 'Acc Reroll Android': 'ra', 'Acc Character + Chrono iOS': 'ci', 'Acc Character + Chrono Android': 'ca', 'Team Meta': 'tm' };
const parseD = (x) => { const m = /^(\d+)\/(\d+)\/(\d+)$/.exec(x || ''); return m ? new Date(+m[3], +m[2] - 1, +m[1], 23, 59, 59) : null; };
const shCodes = this.shared('codes', null);
if (shCodes) { CODES = {}; shCodes.forEach((c) => { const dd = parseD(c.until); CODES[c.code] = { kind: c.kind, val: c.val, min: c.min, cap: c.cap, scope: SC[c.scope] || 'all', scopeLabel: c.scope, until: c.until, expired: c.status === 'expired' || !!(dd && dd < new Date()), paused: c.status === 'paused', full: c.limit > 0 && c.used >= c.limit }; }); }
const evaluate = (raw) => {
const code = (raw || '').trim().toUpperCase();
if (code === '') return null;
const c = CODES[code];
if (!c) return { ok: false, msg: 'Mã “' + code + '” không tồn tại. Kiểm tra lại chính tả.' };
if (c.expired) return { ok: false, msg: 'Mã ' + code + ' đã hết hạn ngày ' + c.until + '.' };
if (c.paused) return { ok: false, msg: 'Mã ' + code + ' đang tạm dừng.' };
if (c.full) return { ok: false, msg: 'Mã ' + code + ' đã hết lượt dùng.' };
if (st.used[code]) return { ok: false, msg: 'Tài khoản của bạn đã dùng mã ' + code + ' rồi. Mỗi mã chỉ dùng 1 lần cho mỗi tài khoản.' };
if (c.scope !== 'all' && c.scope !== it.cat) return { ok: false, msg: 'Mã ' + code + ' chỉ áp dụng cho ' + c.scopeLabel + ', không dùng cho đơn này.' };
if (price < c.min) return { ok: false, msg: 'Đơn cần từ ' + fmt(c.min) + ' để dùng mã ' + code + '.' };
let d = c.kind === 'pct' ? Math.round(price * c.val / 100) : c.val;
if (c.kind === 'pct' && c.cap > 0 && d > c.cap) d = c.cap;
if (d > price) d = price;
return { ok: true, code, discount: d, offer: c.kind === 'pct' ? 'Giảm ' + c.val + '%' + (c.cap > 0 ? ' (tối đa ' + fmt(c.cap) + ')' : '') : 'Giảm ' + fmt(c.val), until: c.until };
};
const res = evaluate(st.tryCode);
const applied = !!(res && res.ok);
const discount = applied ? res.discount : 0;
const total = price - discount;
const enough = wallet >= total;
const remain = wallet - total;
const canPay = st.logged && enough && it.stock > 0;
const sumRows = [{ k: it.isPack ? 'Giá ' + fmt(it.price) + ' × ' + qty : 'Giá acc', v: fmt(price), col: '#1B1530' }];
if (applied) sumRows.push({ k: 'Giảm giá (' + res.code + ')', v: '-' + fmt(discount), col: '#14744E' });
if (it.gift) sumRows.push({ k: 'Quà tặng', v: '1 acc cùng loại', col: '#8A4B00' });

const d = {
pics: (it.pics || []).map((src) => ({ src })), hasPics: !!(it.pics && it.pics.length),
title: it.title, bg: colOf(it), priceText: fmt(it.price) + (it.isPack ? ' / acc' : ''), originalPriceText: fmt(it.originalPrice || 0), salePercent: Number(it.discountPercent) || 0, hasSale: Number(it.discountPercent) > 0, isPack: it.isPack, gift: !!it.gift, stock: it.stock,
info: it.isPack
? [{ k: 'Danh mục', v: cat.name }, { k: 'Còn lại', v: it.stock + ' acc' }, { k: 'Đã bán', v: String(it.sold) }, { k: 'Liên kết', v: 'Bandai Namco ID' }]
: cat.custom ? [{ k: 'Danh mục', v: cat.name }, ...(it.info ? [{ k: 'Thông tin', v: it.info }] : []), { k: 'Liên kết', v: 'Thông tin đăng nhập' }] : [{ k: 'Danh mục', v: cat.name }, { k: 'Cấp độ', v: String(it.level) }, { k: 'Tinh thể', v: it.crystal }, { k: 'Số nhân vật', v: String(it.chars) }, { k: 'Liên kết', v: 'Bandai Namco ID' }]
};

